import{b as e,O as t,g as l,j as c}from"./chunks/framework.DcaUmd3X.js";const d=JSON.parse('{"title":"认知盈余（经典版）","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/cognitive-surplus/index.md","filePath":"读书感悟/电子书架/29.认知盈余.md","lastUpdated":1781614933000}'),p={name:"reading/digital/cognitive-surplus/index.md"};function u(a,o,b,q,k,r){return t(),l("div",null,[...o[0]||(o[0]=[c('<h1 id="认知盈余-经典版" tabindex="-1">认知盈余（经典版） <a class="header-anchor" href="#认知盈余-经典版" aria-label="Permalink to &quot;认知盈余（经典版）&quot;">​</a></h1><p><code>克莱·舍基</code> <code>励志成长</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 是受过教育，并拥有自由支配时间的人，他们有丰富的知识背景，同时有强烈的分享欲望，这些人的时间汇聚在一起，产生巨大的社会效应。</p></blockquote><blockquote><p>📌 平庸是创造性生产的供应增加所必然带来的副作用</p></blockquote><blockquote><p>📌 并不是我们的工具塑造了我们的行为，但是工具赋予了我们行为发生的可能。</p></blockquote><blockquote><p>📌 在心理学文献中，为了阐释自愿参与而设计的实验被称为“自由选择”（free choice）测试</p></blockquote><blockquote><p>📌 人类的动机并不纯粹是附加性的，为了兴趣而做事和为了报酬而做事是截然不同的。</p></blockquote><blockquote><p>📌 如果内在动机存在于人性之中最基本的部分，满足内在动机也会使我们得到满足，那么满足那些动机所使用的工具就应该被推广。</p></blockquote><blockquote><p>📌 工具的性能并不完全决定其最终用途。</p></blockquote><blockquote><p>📌 人在社会环境中的行为会有所节制，会表现得不那么自私。</p></blockquote><blockquote><p>📌 良心就是那个告诉我们可能有人在盯着自己的细小声音</p></blockquote><blockquote><p>📌 点燃蜡烛照亮他人者，不会给自己带来黑暗</p></blockquote><blockquote><p>📌 ；同样，传播思想，无损于思想的传播者</p></blockquote><blockquote><p>📌 只要你做到了这样的结合，你就可以从最基本的方面改变人与人之间的互动方式，从简单到如音乐分享，到复杂到如公民参与这样的人类行为无一例外。</p></blockquote><blockquote><p>📌 社会生产并非一剂万灵药，它只是一种选择。虽然趁它有价值的时候使用它会让我们境况更好，但就像通过公司和政府制度进行的生产一样，它本身也面临着挑战。</p></blockquote><blockquote><p>📌 一个追求共同目标的群体必须保证自己的高效率（否则它就失去了存在的意义），同时必须保证其成员具有满足感（否则其成员就失去了留在组织内的理由）</p></blockquote><blockquote><p>📌 公共价值与公用价值一样需要广泛的交流，但要求参与者更为开放，并与新人和非参与者分享创造出来的价值。</p></blockquote><blockquote><p>📌 你总是可以获得你想要的一切，但是你不能获得你需要的一切。”我们需要的那种价值是由那些追求公共价值的团体创造出来的</p></blockquote><blockquote><p>📌 成本的下降创造了更大的尝试空间，而尝试可以创造出价值，价值会引发盈利的动机。</p></blockquote><blockquote><p>📌 方式、动机和机会三者的融合，从累积的自由时间这个原材料中，生产出了认知盈余。</p></blockquote><blockquote><p>📌 每一个希望大规模驾驭认知盈余的服务都会面临这种此消彼长的关系。你可以拥有大量的用户，你可以拥有活跃的用户群，你也可以拥有志同道合的用户群。但三者中，你只能选择其二，因为你不可能将三者同时拥有。</p></blockquote><blockquote><p>📌 创办了一系列科技企业的创业家布鲁斯特·卡利（Brewster Kahle）曾经说过：“要想解决难题，必须先遇到难题。”提前对成功的后果进行防范会大大减少回报。一般来说，勇于尝新，敢于迎接相继出现的困难，比在没有遇到任何问题的情况下闭门造车更有效。</p></blockquote><blockquote><p>📌 任务的关键并不是要完成某件事，而是要去创造一种让人们愿意去做事的环境</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 思维的固化，导致思想难以持续延伸</p><p>📌 对世界已有的信念和看法会阻碍人们看清现实。</p></blockquote><blockquote><p>💭 多花点时间用于思考</p><p>📌 一旦你弄明白如何通过一种让他人在意的方式来充分利用认知盈余，那么他人也会复制你的技术，一而再再而三地传遍世界。</p></blockquote><blockquote><p>💭 从小到大，从简单到复杂</p><p>📌 社会化媒体中一条名副其实的自然法则是，为了拥有一个大型而优秀的系统，最好从一个小型而优秀的系统做起，并且努力使它变大变强，这样做远远好过从一个大型却平淡无奇的系统做起并努力改进。</p></blockquote>',28)])])}const n=e(p,[["render",u]]);export{d as __pageData,n as default};
